WITH enriched AS (SELECT *, NTILE(4) OVER (ORDER BY sqft DESC, id ASC) sqft_bucket, ROUND(sqft / SUM(sqft) OVER (PARTITION BY city), 4) sqft_share FROM stores) SELECT CASE WHEN sqft_bucket >= 7 THEN 'LARGE' ELSE 'SMALL' END AS sqft_bucket_tier, CASE WHEN sqft_share >= 0.86 THEN 'PREMIUM' ELSE 'STANDARD' END AS sqft_share_tier, ROUND(AVG(sqft_share), 2) AS avg_sqft_share, COUNT(DISTINCT region) AS distinct_regions, COUNT_IF(region = 'Central') AS central_events, COUNT(*) FILTER (WHERE region = 'East') AS east_rows, ROUND(AVG(sqft), 2) AS avg_sqft FROM enriched GROUP BY 1, 2 HAVING ROUND(AVG(sqft), 2) > 0
